import { createContext, useContext, useState, useCallback, type ReactNode } from "react";
import type { RiskTier } from "@/utils/riskScoring";

interface RiskContextValue {
    /** tier per contact id, populated as panels calculate results */
    tiers: Record<string, RiskTier>;
    setTier: (contactId: string, tier: RiskTier) => void;
}

const RiskContext = createContext<RiskContextValue>({
    tiers: {},
    setTier: () => { },
});

export function RiskProvider({ children }: { children: ReactNode }) {
    const [tiers, setTiers] = useState<Record<string, RiskTier>>({});

    const setTier = useCallback((contactId: string, tier: RiskTier) => {
        setTiers((prev) => {
            // avoid unnecessary re-renders
            if (prev[contactId] === tier) return prev;
            return { ...prev, [contactId]: tier };
        });
    }, []);

    return (
        <RiskContext.Provider value={{ tiers, setTier }}>
            {children}
        </RiskContext.Provider>
    );
}

export const useRiskContext = () => useContext(RiskContext);

export type RiskTier = "green" | "yellow" | "red";

export interface RiskFactor {
    label: string;
    points: number;
    detail: string;
    tooltip: string;
}

export interface RiskResult {
    score: number;
    tier: RiskTier;
    confidence: number;
    dataSignals: number;
    positiveFactors: RiskFactor[];
    negativeFactors: RiskFactor[];
    expectedSuccessRate: number;
    recommendation: {
        header: string;
        body: string;
        primaryAction: string;
        secondaryAction: string;
    };
}

export interface ContactForRisk {
    id: string;
    name: string;
    phone: string;
    totalSpent: number;
    reliability?: number;
    lastMessage?: string;
    timestamp: string;
    unread: number;
    status?: string;
    orderStatus?: string;
}

export interface MessageForRisk {
    text: string;
    sent: boolean;
    timestamp: string;
}

// ─── Phone Validation ──────────────────────────────────────────────────────────
function validatePhone(phone: string): "mobile" | "landline" | "invalid" {
    const cleaned = phone.replace(/[\s\-\+]/g, "").replace(/^(00212|212|0)/, "");
    if (cleaned.length !== 9) return "invalid";
    const prefix = cleaned.charAt(0);
    if (prefix === "6" || prefix === "7") return "mobile";
    if (prefix === "5" || prefix === "8") return "landline";
    return "invalid";
}

// ─── Sentiment Analysis ─────────────────────────────────────────────────────────
function analyzeSentiment(text: string): "positive" | "negative" | "neutral" {
    const lower = text.toLowerCase();
    const positive = ["yes", "oui", "ayeh", "wakha", "merci", "chokran", "ok", "okay", "sure", "confirmed", "great", "thanks", "thx"];
    const negative = ["no", "non", "la", "cancel", "annule", "maybe", "inshallah", "not sure", "wait", "later", "problem", "issue"];
    if (positive.some((w) => lower.includes(w))) return "positive";
    if (negative.some((w) => lower.includes(w))) return "negative";
    return "neutral";
}

// ─── Late Night Detection ───────────────────────────────────────────────────────
function isLateNight(timestamp: string): boolean {
    const hour = new Date(timestamp).getHours();
    return hour >= 2 && hour < 6;
}

// ─── Expected Success Rate ──────────────────────────────────────────────────────
function getExpectedSuccessRate(score: number): number {
    if (score >= 90) return 98;
    if (score >= 80) return 94;
    if (score >= 70) return 88;
    if (score >= 60) return 78;
    if (score >= 50) return 65;
    if (score >= 40) return 52;
    if (score >= 30) return 38;
    if (score >= 20) return 25;
    return 15;
}

// ─── Tier ──────────────────────────────────────────────────────────────────────
function getTier(score: number): RiskTier {
    if (score >= 70) return "green";
    if (score >= 40) return "yellow";
    return "red";
}

// ─── Recommendation ────────────────────────────────────────────────────────────
function getRecommendation(
    tier: RiskTier,
    expectedSuccessRate: number,
    totalSpent: number
): RiskResult["recommendation"] {
    if (tier === "green") {
        return {
            header: "PROCEED WITH DELIVERY",
            body: `This customer has consistent payment history and confirmed availability. Expected success rate ${expectedSuccessRate}%.`,
            primaryAction: "Confirm Order",
            secondaryAction: "Request Verification",
        };
    }
    if (tier === "yellow") {
        return {
            header: "REVIEW CAREFULLY",
            body: `Mixed signals detected. Consider calling to verify availability, requesting partial prepayment, or confirming address via WhatsApp. Expected success rate ${expectedSuccessRate}%.`,
            primaryAction: "Call Customer",
            secondaryAction: "Send Verification Message",
        };
    }
    return {
        header: "HIGH RISK — DO NOT SHIP",
        body: `Multiple red flags detected. Suggested action: cancel or require 100% prepayment. Expected loss if shipped: ${totalSpent.toFixed(0)} MAD.`,
        primaryAction: "Cancel Order",
        secondaryAction: "Request Prepayment",
    };
}

// ─── Main Scoring Engine ────────────────────────────────────────────────────────
export function calculateRiskScore(
    contact: ContactForRisk,
    messages: MessageForRisk[]
): RiskResult {
    let score = 50;
    const positive: RiskFactor[] = [];
    const negative: RiskFactor[] = [];
    let criticalFactors = 0;

    const reliability = contact.reliability ?? 5;
    const totalSpent = contact.totalSpent ?? 0;

    // ── Returning Customer ──
    if (reliability >= 8 && totalSpent >= 300) {
        const pts = 20;
        score += pts;
        const orders = Math.max(2, Math.floor(totalSpent / 150));
        positive.push({
            label: "Returning Customer",
            points: pts,
            detail: `${orders} successful orders`,
            tooltip: "Customers with 90%+ success rate and 3+ orders get a significant trust boost.",
        });
    } else if (reliability >= 6) {
        const pts = 10;
        score += pts;
        positive.push({
            label: "Established Customer",
            points: pts,
            detail: `Reliability score ${reliability}/10`,
            tooltip: "Returning customer with decent track record.",
        });
    }

    // ── Response Time (from messages) ──
    if (messages.length > 0) {
        const sentMsgs = messages.filter((m) => m.sent);
        const receivedMsgs = messages.filter((m) => !m.sent);
        if (sentMsgs.length > 0 && receivedMsgs.length > 0) {
            const lastSent = new Date(sentMsgs[sentMsgs.length - 1].timestamp).getTime();
            const lastReceived = new Date(receivedMsgs[receivedMsgs.length - 1].timestamp).getTime();
            const diffMin = Math.abs(lastReceived - lastSent) / 60000;
            if (diffMin < 5) {
                score += 15;
                positive.push({
                    label: "Fast Response Time",
                    points: 15,
                    detail: `${Math.round(diffMin)}m ${Math.round((diffMin % 1) * 60)}s`,
                    tooltip: "Responding in under 5 minutes is a strong trust signal.",
                });
            } else if (diffMin < 30) {
                score += 5;
                positive.push({
                    label: "Good Response Time",
                    points: 5,
                    detail: `${Math.round(diffMin)} minutes`,
                    tooltip: "Responding within 30 minutes shows engagement.",
                });
            }
        }
    }

    // ── Order Value ──
    if (totalSpent > 2000) {
        const pts = 20;
        score -= pts;
        criticalFactors++;
        negative.push({
            label: "Very High Order Value",
            points: -pts,
            detail: `${totalSpent.toFixed(0)} MAD — exceeds 2,000 threshold`,
            tooltip: "Orders over 2,000 MAD carry substantially higher financial risk for COD.",
        });
    } else if (totalSpent > 1000) {
        const pts = 10;
        score -= pts;
        negative.push({
            label: "High Order Value",
            points: -pts,
            detail: `${totalSpent.toFixed(0)} MAD — exceeds 1,000 threshold`,
            tooltip: "Orders between 1,000–2,000 MAD carry moderate financial risk for COD.",
        });
    } else if (totalSpent < 500 && totalSpent > 0) {
        const pts = 5;
        score += pts;
        positive.push({
            label: "Low Value Order",
            points: pts,
            detail: `${totalSpent.toFixed(0)} MAD`,
            tooltip: "Low-value orders have minimal financial risk if not collected.",
        });
    }

    // ── Phone Validation ──
    const phoneStatus = validatePhone(contact.phone);
    if (phoneStatus === "invalid") {
        const pts = 25;
        score -= pts;
        criticalFactors++;
        negative.push({
            label: "Invalid Phone Number",
            points: -pts,
            detail: `"${contact.phone}" does not match expected format`,
            tooltip: "Invalid numbers make follow-up impossible and are a major fraud indicator.",
        });
    } else if (phoneStatus === "landline") {
        const pts = 15;
        score -= pts;
        negative.push({
            label: "Landline Number",
            points: -pts,
            detail: "Landlines are harder to reach for delivery confirmation",
            tooltip: "Mobile phones allow real-time delivery confirmation; landlines do not.",
        });
    }

    // ── Sentiment of Last Message ──
    const lastMsg = contact.lastMessage ?? "";
    const sentiment = analyzeSentiment(lastMsg);
    if (sentiment === "negative") {
        const pts = 15;
        score -= pts;
        negative.push({
            label: "Negative Message Sentiment",
            points: -pts,
            detail: `Last message: "${lastMsg.substring(0, 40)}..."`,
            tooltip: "Hesitation or negative keywords in messages correlate with failed deliveries.",
        });
    } else if (sentiment === "positive") {
        const pts = 5;
        score += pts;
        positive.push({
            label: "Positive Confirmation",
            points: pts,
            detail: `Last message: "${lastMsg.substring(0, 40)}"`,
            tooltip: "Positive keywords (yes, confirmed, merci) indicate willingness to receive.",
        });
    }

    // ── Late Night Order ──
    if (isLateNight(contact.timestamp)) {
        const pts = 10;
        score -= pts;
        negative.push({
            label: "Late Night Order",
            points: -pts,
            detail: `Placed at ${new Date(contact.timestamp).toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit" })}`,
            tooltip: "Orders placed between 02:00–06:00 have higher fraud risk.",
        });
    }

    // ── Unread / No Response ──
    if (contact.unread > 0) {
        const pts = 10;
        score -= pts;
        negative.push({
            label: "Customer Not Responding",
            points: -pts,
            detail: `${contact.unread} unread message${contact.unread > 1 ? "s" : ""}`,
            tooltip: "Unread messages may indicate the customer is avoiding contact.",
        });
    } else if (messages.length > 1) {
        const pts = 15;
        score += pts;
        positive.push({
            label: "Active Conversation",
            points: pts,
            detail: `${messages.length} messages exchanged`,
            tooltip: "Active engagement with the seller is a strong delivery signal.",
        });
    }

    // ── Clamp score ──
    score = Math.max(0, Math.min(100, Math.round(score)));

    const tier = getTier(score);
    const expectedSuccessRate = getExpectedSuccessRate(score);
    const dataSignals = positive.length + negative.length;

    // Confidence: 50% base + 5% per signal + 20% if critical factors + cap at 95%
    const confidence = Math.min(95, 50 + dataSignals * 5 + (criticalFactors > 0 ? 20 : 0));

    return {
        score,
        tier,
        confidence,
        dataSignals,
        positiveFactors: positive,
        negativeFactors: negative,
        expectedSuccessRate,
        recommendation: getRecommendation(tier, expectedSuccessRate, totalSpent),
    };
}

// ─── Quick Tier (contact-only, no messages) ─────────────────────────────────────
// Used for dots in list views (ContactsView, ChatList).
// Deterministic — same inputs always give the same tier.
export function quickTier(contact: {
    phone: string;
    reliability?: number;
    totalSpent?: number;
    orderStatus?: string | null;
    lastMessage?: string;
    timestamp: string;
    unread?: number;
}): RiskTier {
    const result = calculateRiskScore(
        {
            id: "",
            name: "",
            phone: contact.phone,
            reliability: contact.reliability,
            totalSpent: contact.totalSpent ?? 0,
            orderStatus: contact.orderStatus,
            lastMessage: contact.lastMessage,
            timestamp: contact.timestamp,
            unread: contact.unread ?? 0,
        },
        [] // no messages — same for every list view
    );
    return result.tier;
}

